// Define the abstract SortAlgorithm class with template method
public abstract class SortAlgorithm {
    public void sort(int[] array) {
        int n = array.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                compare(array[j], array[j + 1]);
            }
            swap(array, 0, n - i - 1);
        }
    }

    // Abstract method to compare elements
    public abstract void compare(int a, int b);

    // Abstract method to swap elements
    public abstract void swap(int[] array, int i, int j);
}

// Implement BubbleSort as a concrete subclass
public class BubbleSort extends SortAlgorithm {
    @Override
    public void compare(int a, int b) {
        if (a > b) {
            swap(array, i, j);
        }
    }

    @Override
    public void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

// Implement SelectionSort as another concrete subclass
public class SelectionSort extends SortAlgorithm {
    @Override
    public void compare(int a, int b) {
        if (a > b) {
            swap(array, i, j);
        }
    }

    @Override
    public void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

// Test the implementation
public class Main {
    public static void main(String[] args) {
        int[] array = {64, 34, 25, 12, 22, 11, 90};

        BubbleSort bubbleSort = new BubbleSort();
        bubbleSort.sort(array);
        System.out.println("Sorted array using BubbleSort: " + java.util.Arrays.toString(array));

        SelectionSort selectionSort = new SelectionSort();
        selectionSort.sort(array);
        System.out.println("Sorted array using SelectionSort: " + java.util.Arrays.toString(array));
    }
}
